'use strict';
let page='dashboard',adminLoadToken=0,tenantData=[],invoiceData=[],tenantCursor=null,invoiceCursor=null,tenantQuery='',tenantTimer=null;const tabs={dashboard:'Dashboard',tenants:'Data Mitra',invoices:'Pembayaran',settings:'Pengaturan'};
const notice=$('notice');
function msg(s,bad=false){notify(notice,s,bad)}
async function loginState(){try{const u=await api('/auth/me');if(u.user.role!=='SUPER_ADMIN')throw Error('Akun ini bukan Super Admin');if(u.user.mustChangePin){requirePinChange();return;}showApp();}catch{$('loginPage').classList.remove('hidden');$('adminPage').classList.add('hidden');}}
function requirePinChange(){
 $('loginPage').classList.remove('hidden');$('adminPage').classList.add('hidden');
 $('loginForm').classList.add('hidden');$('changePinForm').classList.remove('hidden');
}
function showApp(){$('loginForm').classList.remove('hidden');$('changePinForm').classList.add('hidden');$('loginPage').classList.add('hidden');$('adminPage').classList.remove('hidden');openTab('dashboard')}
async function openTab(tab){page=tab;const token=++adminLoadToken;clearTimeout(tenantTimer);msg('');$('menu').innerHTML=Object.keys(tabs).map(k=>`<button class="navbtn ${k===tab?'active':''}" data-nav="${k}">${tabs[k]}</button>`).join('');document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>openTab(b.dataset.nav));$('title').textContent=tabs[tab];try{
  if(tab==='dashboard'){const overview=await api('/admin/overview');if(token===adminLoadToken&&page===tab)renderDashboard(overview)}
  if(tab==='tenants')await loadTenantPage(true);
  if(tab==='invoices')await loadInvoicePage(true);
  if(tab==='settings'){const overview=await api('/admin/overview');if(token===adminLoadToken&&page===tab)renderSettings(overview.config)}
}catch(e){msg(e.message,true)}}
function renderDashboard(o){$('screen').innerHTML=`<div class="stats"><div class="stat"><span>Jumlah Mitra</span><b>${o.tenants}</b></div><div class="stat"><span>Menunggu Pembayaran</span><b>${o.pending}</b></div><div class="stat"><span>Jumlah Produk</span><b>${o.products}</b></div></div><div class="card"><h2>Kontrol INPOS</h2><p class="sub">Gunakan Data Mitra untuk mengatur status usaha, Pembayaran untuk menyetujui QRIS manual, dan Pengaturan untuk mengelola tarif serta URL gambar QRIS.</p></div>`;}
async function loadTenantPage(reset){if(reset){tenantData=[];tenantCursor=null;}const token=adminLoadToken,q=tenantQuery;const query=new URLSearchParams({limit:'80',q});if(tenantCursor)query.set('cursor',tenantCursor);
 const result=await api('/admin/tenants?'+query);if(token!==adminLoadToken||page!=='tenants'||q!==tenantQuery)return;
 tenantData.push(...result.items);tenantCursor=result.nextCursor;renderTenants(tenantData);
}
async function loadInvoicePage(reset){if(reset){invoiceData=[];invoiceCursor=null;}const token=adminLoadToken;const query=new URLSearchParams({limit:'80'});if(invoiceCursor)query.set('cursor',invoiceCursor);
 const result=await api('/admin/invoices?'+query);if(token!==adminLoadToken||page!=='invoices')return;
 invoiceData.push(...result.items);invoiceCursor=result.nextCursor;renderInvoices(invoiceData);
}
function renderTenants(rows){$('screen').innerHTML=`<div class="card"><div class="toolbar"><input class="search-input" id="qTenants" placeholder="Cari toko / subdomain" value="${esc(tenantQuery)}"></div><div id="tenantRows"></div><div class="toolbar" id="tenantPager"></div></div>`;
function draw(){const q=tenantQuery.toLowerCase();$('tenantRows').innerHTML=`<div class="table-scroll"><table class="table"><thead><tr><th>Usaha</th><th>Status</th><th>Masa Aktif</th><th>Aksi</th></tr></thead><tbody>${rows.filter(t=>(t.name+t.slug).toLowerCase().includes(q)).map(t=>`<tr><td><b>${esc(t.name)}</b><br><small>${esc(t.slug)}.inpos.id</small></td><td><span class="pill ${t.status==='ACTIVE'?'success':'warn'}">${esc(t.status)}</span></td><td>${t.subscriptionEndsAt?new Date(t.subscriptionEndsAt).toLocaleDateString('id-ID'):'Trial: '+new Date(t.trialEndsAt).toLocaleDateString('id-ID')}</td><td><button class="btn small ${t.status==='SUSPENDED'?'':'danger'}" data-id="${t.id}" data-suspend="${t.status==='SUSPENDED'?'false':'true'}">${t.status==='SUSPENDED'?'Aktifkan':'Tangguhkan'}</button></td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-suspend]').forEach(b=>b.onclick=()=>changeStatus(b.dataset.id,b.dataset.suspend==='true'))} $('qTenants').oninput=()=>{tenantQuery=$('qTenants').value;adminLoadToken++;clearTimeout(tenantTimer);tenantTimer=setTimeout(()=>loadTenantPage(true).catch(e=>msg(e.message,true)),250)};draw();$('tenantPager').innerHTML=tenantCursor?'<button id="moreTenants" class="btn">Tampilkan mitra lainnya</button>':'';$('moreTenants')?.addEventListener('click',()=>loadTenantPage(false).catch(e=>msg(e.message,true)));}
async function changeStatus(id,suspended){if(!confirm(suspended?'Tangguhkan usaha ini?':'Aktifkan kembali usaha ini?'))return;try{await api('/admin/tenants/'+id+'/suspend','PATCH',{suspended});msg('Status toko berhasil diperbarui');await loadTenantPage(true)}catch(e){msg(e.message,true)}}
function renderInvoices(rows){$('screen').innerHTML=`<div class="card"><h2>Validasi Pembayaran Manual</h2><p class="sub">Setujui hanya setelah nominal dan bukti pembayaran benar-benar diverifikasi. Sistem starter belum terhubung webhook pembayaran.</p><div class="table-scroll"><table class="table"><thead><tr><th>Toko</th><th>Jenis</th><th>Nominal</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.tenant.name)}</b><br><small>${esc(p.tenant.slug)}</small></td><td>${esc(p.type)} · ${p.months} bulan</td><td><b>${fmt(p.total)}</b><br><small>Rp ${new Intl.NumberFormat('id-ID').format(p.amount)} + ${String(p.uniqueCode).padStart(3,'0')}</small></td><td>${esc(p.status)}</td><td>${p.status==='PENDING'?`<button data-id="${p.id}" data-decision="approve" class="btn small">Setujui</button><button data-id="${p.id}" data-decision="reject" class="btn small danger">Tolak</button>`:'—'}</td></tr>`).join('')}</tbody></table></div><div class="toolbar" id="invoicePager"></div></div>`;$('invoicePager').innerHTML=invoiceCursor?'<button id="moreInvoices" class="btn">Tampilkan tagihan lainnya</button>':'';$('moreInvoices')?.addEventListener('click',()=>loadInvoicePage(false).catch(e=>msg(e.message,true)));document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>decide(b.dataset.id,b.dataset.decision));}
async function decide(id,action){if(!confirm(action==='approve'?'Saya sudah memverifikasi pembayaran. Setujui tagihan ini?':'Tolak tagihan ini?'))return;try{await api('/admin/invoices/'+id+'/'+action,'POST',{});await loadInvoicePage(true);msg('Tagihan berhasil diproses')}catch(e){msg(e.message,true)}}
function renderSettings(c){$('screen').innerHTML=`<div class="card"><h2>Tarif & QRIS</h2><form id="settingsForm" class="stack form-grid"><label>Langganan per bulan (Rp)<input name="subscriptionPrice" type="number" min="0" required value="${Number(c.subscriptionPrice)||0}"></label><label>Lisensi Pajak per bulan (Rp)<input name="taxLicensePrice" type="number" min="0" required value="${Number(c.taxLicensePrice)||0}"></label><label>Masa Trial Pendaftaran (hari)<input name="trialDays" type="number" min="1" max="365" required value="${Number(c.trialDays)||60}"></label><label class="full">URL Gambar QRIS resmi (HTTPS)<input name="qrisImageUrl" placeholder="https://.../qris.png" value="${esc(c.qrisImageUrl||'')}"></label><div class="full"><button class="btn red">Simpan Pengaturan</button></div></form><p class="sub">Unggah file gambar QRIS ke penyimpanan HTTPS Anda terlebih dahulu. Sistem ini tidak menyimpan gambar QRIS melalui API.</p></div>`;
$('settingsForm').onsubmit=async e=>{e.preventDefault();const d=formData(e.target);try{await api('/admin/settings','PATCH',{subscriptionPrice:Number(d.subscriptionPrice),taxLicensePrice:Number(d.taxLicensePrice),trialDays:Number(d.trialDays),qrisImageUrl:d.qrisImageUrl});msg('Pengaturan berhasil disimpan')}catch(err){msg(err.message,true)}};}
$('loginForm').onsubmit=async e=>{e.preventDefault();try{const res=await api('/auth/admin/login','POST',formData(e.target));notify($('loginMessage'),'');if(res.user.mustChangePin)requirePinChange();else showApp()}catch(err){notify($('loginMessage'),err.message,true)}};
$('changePinForm').onsubmit=async e=>{e.preventDefault();try{await api('/auth/change-pin','POST',formData(e.target));$('changePinForm').classList.add('hidden');showApp();}catch(err){notify($('loginMessage'),err.message,true)}};
$('logout').onclick=async()=>{try{await api('/auth/logout','POST',{})}catch(e){return msg('Logout gagal: '+e.message,true)}adminLoadToken++;csrf='';$('adminPage').classList.add('hidden');$('loginPage').classList.remove('hidden');$('loginForm').classList.remove('hidden');$('changePinForm').classList.add('hidden');};
loginState();
